// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [
    enhanceSlideboxRange(input, { layers: true }),
    enhanceSlideboxRangeFill(input),
  ],
);

(function (demo, signal) {
  const button = demo.querySelector("[data-chart]");
  const chart = demo.querySelector(".light-chart");
  button.addEventListener(
    "click",
    () => {
      const previous = button.getAttribute("aria-pressed") !== "true";
      const values = previous
        ? [330, 240, 480, 390, 520, 290, 450]
        : [180, 420, 310, 540, 380, 610, 400];
      button.setAttribute("aria-pressed", String(previous));
      button.textContent = previous ? "Show this week" : "Show previous week";
      chart.setAttribute("aria-label", `Sample visits: ${values.join(", ")}`);
      [...chart.children].forEach((bar, index) =>
        bar.style.setProperty(
          "--bar",
          `${(values[index] / Math.max(...values)) * 100}%`,
        ),
      );
      demo.querySelector("[data-chart-total]").textContent =
        `${values.reduce((sum, value) => sum + value, 0).toLocaleString("en-US")} visits`;
    },
    { signal },
  );
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
